SELECT LAG(SUM(x0.v53153 / x0.v53154), 96, 1 + SUM(x0.v53156 / x0.v53154)) OVER (ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), RANK() OVER (ORDER BY CASE WHEN @var IS NULL THEN 'null' ELSE 0 END DESC, NTH_VALUE(x0.v53154, 1) OVER ()) FROM v53152 AS x0 WINDOW x1 AS (ORDER BY COUNT(*) OVER () ROWS BETWEEN INTERVAL '2:2' MINUTE_SECOND PRECEDING AND UNBOUNDED FOLLOWING)